document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();$('#workarea').classList.add('dragover');}});document.addEventListener('dragleave',e=>{if(!e.relatedTarget)$('#workarea').classList.remove('dragover');});document.addEventListener('drop',e=>{if(e.dataTransfer.files.length){e.preventDefault();$('#workarea').classList.remove('dragover');importFiles([...e.dataTransfer.files]);}});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('#modal').open)return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey?1:-1);}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();undo(1);}if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateObject();}if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();}if(mod&&e.key.toLowerCase()==='c'&&obj()){clipboard=structuredClone(obj());}if(mod&&e.key.toLowerCase()==='v'&&clipboard&&page()){const o=structuredClone(clipboard);o.id=uid();o.x+=15;o.y+=15;page().objects.push(o);selected=o.id;checkpoint();refresh();}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteObject();}if(e.key==='Escape'){tool='select';selected=null;drawOverlay();inspector();}if(obj()&&e.key.startsWith('Arrow')){e.preventDefault();const d=e.shiftKey?10:1;if(e.key==='ArrowLeft')obj().x-=d;if(e.key==='ArrowRight')obj().x+=d;if(e.key==='ArrowUp')obj().y-=d;if(e.key==='ArrowDown')obj().y+=d;checkpoint();drawOverlay();inspector();}});
